def prefixSuffixString(s1, s2):
    count = 0
    for s2_str in s2:
        len_s2 = len(s2_str)
        for s1_str in s1:
            if len_s2 <= len(s1_str):
                if s2_str == s1_str[:len_s2] or s2_str == s1_str[-len_s2:]:
                    count += 1
                    break
    return count
